.watch-glass-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  cursor: pointer;
}
.watch-glass-svg {
  width: 80px;
  height: 32px;
  transition: transform 0.2s, filter 0.2s;
  filter: drop-shadow(0 1px 4px rgba(0,0,0,0.06));
}
.watch-glass-svg.hovered {
  transform: scale(1.06);
  filter: drop-shadow(0 3px 8px rgba(0,0,0,0.1));
}

